import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listSubjectsHandler } from "../handlers/listSubjectsHandler";
import type { ApiError } from "../runtime/client";
import type { SubjectStatus } from "../types/SubjectStatus";

type Data = Awaited<ReturnType<typeof listSubjectsHandler>>;

export function useListSubjects(
  bookmark?: string | null,
  status?: SubjectStatus | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listSubjects", bookmark, status],
    queryFn: () => listSubjectsHandler(bookmark, status),
    ...options,
  });
}
